def complement(sequence, reverse=False):
    """
        Compute the complement of a DNA sequence.

        If reverse is True, reverse it too.
    """
    flip = {
        'A': 'T',
        'C': 'G',
        'G': 'C',
        'T': 'A'
    }
    revcomp = []
    for i in list(sequence):
        revcomp.append(flip[i])

    if reverse:
        return ''.join(revcomp[::-1])
    return ''.join(revcomp)

